public class Main {
    static StringBuilder sb = new StringBuilder();
    static void a() {
        try {
            sb.append("1");
            b();
            sb.append("2");
        } catch (Exception e) {
            sb.append("3");
        } finally {
            sb.append("4");
        }
    }
    static void b() throws Exception {
        sb.append("5");
        throw new Exception();
    }
    public static void main(String[] args) {
        a();
        sb.append("6");
        System.out.println(sb.toString());
    }
}

public class Main {
  int base;
  Main(int base) { this.base = base; }
  int calc() {
    int result = 0;
    int n = base;
    while (n > 0) {
      result += n * n;
      n--;
    }
    return result;
  }
  public static void main(String[] args) {
    Main obj = new Main(4);
    int r = obj.calc();
    System.out.print(r);
  }
}

def func(s):
    words = s.split()
    freq = {}
    for w in words:
        freq[w] = freq.get(w, 0) + 1
    return max(freq, key=freq.get)

s = "banana apple banana grape banana apple"
print(func(s))

